import { Activity, AlertTriangle, Database, Radio, Shield, Users } from "lucide-react";
import { useCompanyLiveStats, usePlatformHealth } from "@/hooks/useCompanyLiveData";

export function CompanyLiveStatsBar() {
  const { data: stats, isLoading } = useCompanyLiveStats();
  const { data: health } = usePlatformHealth();

  if (isLoading || !stats) {
    return (
      <div className="mb-8 rounded-xl border border-border/40 bg-muted/20 px-4 py-3 text-sm text-muted-foreground animate-pulse">
        Loading live platform metrics…
      </div>
    );
  }

  const healthLabel =
    health === "operational" ? "Operational" : health === "degraded" ? "Degraded" : "Checking…";
  const healthClass =
    health === "operational" ? "text-emerald-400" : health === "degraded" ? "text-amber-400" : "text-slate-400";

  const tiles = [
    { icon: Database, label: "Threat items", value: stats.threatItems.toLocaleString() },
    { icon: Shield, label: "Critical", value: stats.criticalThreats.toLocaleString() },
    { icon: Radio, label: "Sources", value: `${stats.activeSources - stats.errorSources}/${stats.activeSources}` },
    { icon: Activity, label: "Open cases", value: stats.openCases.toLocaleString() },
    { icon: Users, label: "Users", value: stats.authorizedUsers.toLocaleString() },
  ];

  return (
    <div className="mb-8 rounded-xl border border-cyan-500/15 bg-gradient-to-r from-cyan-500/5 to-indigo-500/5 overflow-hidden">
      <div className="flex flex-wrap items-center gap-x-6 gap-y-2 px-4 py-3 border-b border-border/30 text-xs">
        <span className="flex items-center gap-2">
          <span className="relative flex h-2 w-2">
            {health === "operational" && (
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-50" />
            )}
            <span className={`relative inline-flex rounded-full h-2 w-2 ${health === "operational" ? "bg-emerald-500" : health === "degraded" ? "bg-amber-500" : "bg-slate-500"}`} />
          </span>
          <span className={`font-semibold ${healthClass}`}>{healthLabel}</span>
          <span className="text-muted-foreground">· live from Supabase</span>
        </span>
        {stats.errorSources > 0 && (
          <span className="flex items-center gap-1 text-amber-400">
            <AlertTriangle className="h-3.5 w-3.5" />
            {stats.errorSources} feed source(s) in error
          </span>
        )}
        {stats.lastIngestAt && (
          <span className="text-muted-foreground">
            Last ingest: {new Date(stats.lastIngestAt).toLocaleString()}
          </span>
        )}
      </div>
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 divide-x divide-y sm:divide-y-0 divide-border/20">
        {tiles.map(({ icon: Icon, label, value }) => (
          <div key={label} className="min-w-0 px-3 sm:px-4 py-3 flex items-center gap-2 sm:gap-3">
            <Icon className="h-4 w-4 text-cyan-400/70 shrink-0" />
            <div>
              <p className="text-lg font-bold tabular-nums leading-none">{value}</p>
              <p className="text-[10px] uppercase tracking-wider text-muted-foreground mt-1">{label}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
