import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useUser, signOut as clerkSignOut } from "@/lib/auth-adapter";
import { ThemeToggle } from "@/components/ThemeToggle";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Shield, LogOut, Pencil, Plus, Trash2, ArrowRight, Sparkles,
  LayoutGrid, RotateCcw, X,
} from "lucide-react";
import { MODULE_ICONS, type PlatformModule } from "@/config/platform-modules";
import { DIVISION_CATEGORY_LABELS } from "@/config/company-divisions";
import { usePlatformModules } from "@/hooks/usePlatformModules";
import { useToast } from "@/hooks/use-toast";
import { useRole } from "@/contexts/RoleContext";
import { CompanyLiveStatsBar } from "@/components/company/CompanyLiveStatsBar";
import { useCompanyLiveStats } from "@/hooks/useCompanyLiveData";

function ModuleCard({
  mod,
  categoryLabel,
  editMode,
  onOpen,
  onEdit,
  onDelete,
}: {
  mod: PlatformModule;
  categoryLabel?: string;
  editMode: boolean;
  onOpen: () => void;
  onEdit: () => void;
  onDelete: () => void;
}) {
  const Icon = MODULE_ICONS[mod.icon] ?? Shield;
  const isLive = mod.status === "live" && !!mod.route;

  return (
    <div
      className={`group relative flex h-full flex-col rounded-2xl border bg-card/60 backdrop-blur-sm overflow-hidden transition-all duration-300 ${
        isLive
          ? "border-cyan-500/20 hover:border-cyan-400/40 hover:shadow-[0_0_32px_rgba(6,182,212,0.12)] cursor-pointer"
          : "border-border/60 opacity-90"
      }`}
      onClick={() => !editMode && isLive && onOpen()}
      onKeyDown={(e) => e.key === "Enter" && !editMode && isLive && onOpen()}
      role={isLive && !editMode ? "button" : undefined}
      tabIndex={isLive && !editMode ? 0 : undefined}
    >
      <div className={`h-1.5 bg-gradient-to-r ${mod.gradient}`} />
      <div className="flex flex-1 flex-col p-6">
        <div className="flex items-start justify-between gap-3 mb-4">
          <div
            className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br ${mod.gradient} shadow-lg`}
          >
            <Icon className="h-6 w-6 text-white" />
          </div>
          <div className="flex items-center gap-1.5">
            {mod.locked && (
              <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full bg-cyan-500/15 text-cyan-400 border border-cyan-500/25">
                Core
              </span>
            )}
            <span
              className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full border ${
                isLive
                  ? "bg-emerald-500/15 text-emerald-400 border-emerald-500/25"
                  : "bg-slate-500/15 text-slate-400 border-slate-500/25"
              }`}
            >
              {isLive ? "Live" : "Coming soon"}
            </span>
          </div>
        </div>

        <h3 className="font-display text-lg font-bold text-foreground mb-1.5">{mod.title}</h3>
        {categoryLabel && (
          <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-2">{categoryLabel}</p>
        )}
        <p className="text-sm text-muted-foreground flex-1 leading-relaxed">{mod.description}</p>

        <div className="mt-5 flex items-center justify-between gap-2">
          {editMode ? (
            <div className="flex gap-2 w-full">
              <Button
                size="sm"
                variant="outline"
                className="flex-1"
                onClick={(e) => { e.stopPropagation(); onEdit(); }}
              >
                <Pencil className="h-3.5 w-3.5 mr-1.5" />
                Rename
              </Button>
              {!mod.locked && (
                <Button
                  size="sm"
                  variant="ghost"
                  className="text-destructive hover:text-destructive"
                  onClick={(e) => { e.stopPropagation(); onDelete(); }}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              )}
            </div>
          ) : isLive ? (
            <span className="inline-flex items-center gap-1.5 text-sm font-medium text-cyan-400 group-hover:gap-2.5 transition-all">
              Open module
              <ArrowRight className="h-4 w-4" />
            </span>
          ) : (
            <span className="text-xs text-muted-foreground">Configure name in edit mode</span>
          )}
        </div>
      </div>
    </div>
  );
}

export default function PlatformHub() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const { isAdmin } = useRole();
  const { modules, updateModule, addModule, removeModule, resetModules } = usePlatformModules();
  const visibleModules = modules.filter((m) => !m.adminOnly || isAdmin);
  const { data: liveStats } = useCompanyLiveStats();
  const { user } = useUser();
  const email = user?.primaryEmailAddress?.emailAddress ?? "";
  const [editMode, setEditMode] = useState(false);
  const [editing, setEditing] = useState<PlatformModule | null>(null);
  const [draftTitle, setDraftTitle] = useState("");
  const [draftDesc, setDraftDesc] = useState("");

  const signOut = async () => {
    await clerkSignOut();
  };

  const openModule = (mod: PlatformModule) => {
    if (mod.route) navigate(mod.route);
  };

  const startEdit = (mod: PlatformModule) => {
    setEditing(mod);
    setDraftTitle(mod.title);
    setDraftDesc(mod.description);
  };

  const saveEdit = () => {
    if (!editing) return;
    updateModule(editing.id, {
      title: draftTitle.trim() || editing.title,
      description: draftDesc.trim() || editing.description,
    });
    setEditing(null);
    toast({ title: "Block updated", description: `"${draftTitle}" saved.` });
  };

  return (
    <div className="min-h-screen bg-background">
      <div
        className="pointer-events-none fixed inset-0 opacity-40"
        style={{
          background:
            "radial-gradient(ellipse 80% 50% at 50% -20%, rgba(6,182,212,0.15), transparent), radial-gradient(ellipse 60% 40% at 100% 100%, rgba(99,102,241,0.1), transparent)",
        }}
      />

      <header className="sticky top-0 z-40 flex h-14 items-center gap-3 px-4 md:px-8 header-glass border-b border-border/40">
        <div className="flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-gradient-to-br from-cyan-500/20 to-indigo-500/20 border border-cyan-500/30">
            <Shield className="h-4 w-4 text-cyan-400" />
          </div>
          <span
            className="text-xs font-semibold uppercase tracking-widest hidden sm:block"
            style={{
              background: "linear-gradient(90deg, #22d3ee, #818cf8)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text",
            }}
          >
            ThreatLens · SOC Platform
          </span>
        </div>
        <div className="ml-auto flex items-center gap-2">
          <span className="hidden md:block text-xs text-muted-foreground truncate max-w-[200px]">{email}</span>
          <ThemeToggle />
          <Button variant="ghost" size="sm" onClick={signOut} className="text-muted-foreground">
            <LogOut className="h-4 w-4 sm:mr-1.5" />
            <span className="hidden sm:inline">Sign out</span>
          </Button>
        </div>
      </header>

      <main className="relative mx-auto max-w-7xl px-4 py-10 md:px-8 md:py-14">
        <div className="mb-10 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <div className="inline-flex items-center gap-2 rounded-full border border-cyan-500/20 bg-cyan-500/10 px-3 py-1 text-xs text-cyan-400 mb-4">
              <Sparkles className="h-3.5 w-3.5" />
              Platform workspace
            </div>
            <h1 className="font-display text-3xl md:text-4xl font-bold text-foreground tracking-tight">
              ThreatLens Cybersecurity Company
            </h1>
            <p className="mt-2 text-muted-foreground max-w-xl">
              Full-stack security organization — {visibleModules.length} divisions.
              {liveStats
                ? ` ${liveStats.threatItems.toLocaleString()} live threat items · ${liveStats.activeSources} feed sources · ${liveStats.authorizedUsers} users.`
                : " Metrics load from Supabase in real time."}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button
              variant={editMode ? "default" : "outline"}
              size="sm"
              onClick={() => setEditMode((v) => !v)}
            >
              {editMode ? <X className="h-4 w-4 mr-1.5" /> : <Pencil className="h-4 w-4 mr-1.5" />}
              {editMode ? "Done editing" : "Edit blocks"}
            </Button>
            {editMode && (
              <>
                <Button variant="outline" size="sm" onClick={addModule}>
                  <Plus className="h-4 w-4 mr-1.5" />
                  Add block
                </Button>
                <Button variant="ghost" size="sm" onClick={resetModules} className="text-muted-foreground">
                  <RotateCcw className="h-4 w-4 mr-1.5" />
                  Reset
                </Button>
              </>
            )}
          </div>
        </div>

        <CompanyLiveStatsBar />

        <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-5 auto-rows-fr">
          {visibleModules.map((mod) => (
            <ModuleCard
              key={mod.id}
              mod={mod}
              categoryLabel={mod.category ? DIVISION_CATEGORY_LABELS[mod.category] : undefined}
              editMode={editMode}
              onOpen={() => openModule(mod)}
              onEdit={() => startEdit(mod)}
              onDelete={() => removeModule(mod.id)}
            />
          ))}

          {editMode && (
            <button
              type="button"
              onClick={addModule}
              className="flex min-h-[220px] flex-col items-center justify-center gap-3 rounded-2xl border-2 border-dashed border-border/60 bg-muted/20 text-muted-foreground hover:border-cyan-500/40 hover:text-cyan-400 hover:bg-cyan-500/5 transition-all"
            >
              <div className="flex h-12 w-12 items-center justify-center rounded-xl border border-dashed border-current">
                <Plus className="h-6 w-6" />
              </div>
              <span className="text-sm font-medium">Add new block</span>
            </button>
          )}
        </div>

        <div className="mt-12 flex items-center gap-2 text-xs text-muted-foreground">
          <LayoutGrid className="h-3.5 w-3.5" />
          <span>
            {visibleModules.length} divisions
            {liveStats ? ` · ${liveStats.threatItems.toLocaleString()} threat items in database` : " · loading live metrics…"}
          </span>
        </div>
      </main>

      <Dialog open={!!editing} onOpenChange={(o) => !o && setEditing(null)}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Rename block</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <label className="block space-y-1.5">
              <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Block name</span>
              <Input
                value={draftTitle}
                onChange={(e) => setDraftTitle(e.target.value)}
                placeholder="e.g. Threat Intel, SOC Ops, GRC…"
                disabled={editing?.locked}
              />
            </label>
            <label className="block space-y-1.5">
              <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Description</span>
              <Textarea
                value={draftDesc}
                onChange={(e) => setDraftDesc(e.target.value)}
                placeholder="What this module is for…"
                rows={3}
              />
            </label>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEditing(null)}>Cancel</Button>
            <Button onClick={saveEdit} disabled={editing?.locked && !draftDesc}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
